// BEGIN 掉落兜底
// 发放口径：背包放得下的进背包，放不下的部分直接掉在玩家脚下，由玩家自己拾取。
// 掉落之后的命运（15 秒的归属保护、之后任何人都能捡、到期自然消失）全部走
// 服务端 MapItem 的既有逻辑，脚本不干预、也不额外统计。
//
// 两个必须守住的服务端契约：
//   1. 掉落件的构造口径要和 cm.gainItem() 一致，否则「地上的」和「包里的」品质不同。
//      gainItem 对装备走 getEquipById()，并给升级次数为 0 的饰品补 3 次；
//      是否 randomizeStats 取决于调用方传进来的 随机潜能（必须与进背包那条路相同）。
//   2. fieldLimit 带 DROP_LIMIT 的地图会静默吞掉掉落（内部降级成
//      disappearingItemDrop，连返回值都没有），所以落地前先自查一次。
var 掉落_装备栏编号 = 1;
var 掉落_道具类 = Java.type("org.gms.client.inventory.Item");
var 掉落_常量类 = Java.type("org.gms.constants.inventory.ItemConstants");
var 掉落_限制类 = Java.type("org.gms.server.maps.FieldLimit");

function 掉落_信息() {
    return Java.type("org.gms.server.ItemInformationProvider").getInstance();
}

// 造一件用于掉落的道具：装备恒为 1 件，其它按堆叠件。
function 掉落_造件(道具ID, 数量, 随机潜能) {
    if (Math.floor(道具ID / 1000000) === 掉落_装备栏编号) {
        var 件 = 掉落_信息().getEquipById(道具ID);
        if (件 === null || 件 === undefined) {
            return null;
        }
        try {
            if (掉落_常量类.isAccessory(道具ID) && 件.getUpgradeSlots() <= 0) {
                件.setUpgradeSlots(3);
            }
        } catch (e) { }
        if (随机潜能) {
            try {
                件 = 掉落_信息().randomizeStats(件);
            } catch (e) { }
        }
        return 件;
    }
    return new 掉落_道具类(道具ID, 0, 数量);
}

// 把 数量 个 道具ID 掉在玩家脚下；返回 true 表示确实掉出去了。
// ffa=false = 常规掉落：15 秒内归自己（同队队员可立即拾取），之后任何人都能捡。
function 掉落_地面(chr, 道具ID, 数量, 随机潜能) {
    try {
        var 地图 = chr.getMap();
        if (掉落_限制类.DROP_LIMIT.check(地图.getFieldLimit())) {
            return false;
        }
        var 件 = 掉落_造件(道具ID, 数量, 随机潜能);
        if (件 === null || 件 === undefined) {
            return false;
        }
        地图.spawnItemDrop(chr, chr, 件, chr.getPosition(), false, false);
        return true;
    } catch (e) {
        return false;
    }
}

// 发一个：放得下就进背包，放不下就掉地上。返回 '包' / '地' / ''（发不出去）。
// cm.canHold() 是只读预检（Inventory.checkSpots），所以可以逐件先问一次，
// 不会触发 gainItem 内部那句「您的背包已满…」（50 连抽会刷 50 条）。
function 掉落_发一个(chr, 道具ID, 随机潜能) {
    if (cm.canHold(道具ID, 1)) {
        var 结果 = cm.gainItem(道具ID, 1, 随机潜能, true);
        if (结果 !== null && 结果 !== undefined) {
            return '包';
        }
    }
    return 掉落_地面(chr, 道具ID, 1, 随机潜能) ? '地' : '';
}
// END 掉落兜底

var status = -1;
var 选中 = null;

function start() {
    status = -1;
    action(1, 0, 0);
}

function action(mode, type, selection) {
    if (mode === -1 || mode === 0) {
        cm.dispose();
        return;
    }
    status++;
    if (status === 0) {
        cm.sendSimple(抽奖菜单());
    } else if (status === 1) {
        选择卷(selection);
    } else if (status === 2) {
        开抽();
    } else {
        cm.dispose();
    }
}

// ============================================================
// 界面
// ============================================================
function 抽奖菜单() {
    var 文本 = "#e#d【起源之塔 · 起源抽奖】#k#n\r\n";
    文本 += "消耗 1 张抽奖卷即可抽取对应次数，奖池共 #r" + 奖池().length + "#k 件装备。\r\n";
    文本 += "#d同一批连抽内不会抽到重复的装备。#k\r\n";
    文本 += "#d装备栏放不下的奖品会直接掉在你脚下，需要自己拾取。#k\r\n";
    文本 += "#d----------------------------------------#k\r\n";
    文本 += "#e#b请选择要使用的抽奖卷：#k#n\r\n";
    for (var i = 0; i < 抽奖卷.length; i++) {
        var 卷 = 抽奖卷[i];
        var 持有 = cm.getPlayer().getItemQuantity(卷[0], false);
        文本 += "#L" + i + "##i" + 卷[0] + "# #t" + 卷[0] + "#\t#b" + 卷[1] + " 连抽#k"
            + "  (持有 #r" + 持有 + "#k)\r\n";
    }
    return 文本;
}

function 选择卷(selection) {
    if (selection < 0 || selection >= 抽奖卷.length) {
        cm.sendOk("无效的选择。");
        cm.dispose();
        return;
    }
    选中 = 抽奖卷[selection];
    var 文本 = "确定使用 1 张 #b#t" + 选中[0] + "##k 抽取 #r" + 选中[1] + "#k 次吗？\r\n";
    文本 += "#d本次 #r" + 选中[1] + "#k 件互不重复。#k\r\n";
    if (!cm.canHold(1010000, 选中[1])) {
        文本 += "\r\n#r#e注意：装备栏空间不足#k#n\r\n放不下的奖品会 #b直接掉在你脚下#k，"
            + "需要#r自己拾取#k，长时间不捡会消失。\r\n";
    }
    cm.sendYesNo(文本 + "\r\n");
}

// ============================================================
// 抽奖
// ============================================================
function 开抽() {
    var chr = cm.getPlayer();
    var 卷ID = 选中[0], 次数 = 选中[1];

    if (chr.getItemQuantity(卷ID, false) < 1) {
        cm.sendOk("你没有这张抽奖卷。\r\n\r\n可以先去 #b积分商店#k 用起源积分兑换。");
        cm.dispose();
        return;
    }
    cm.gainItem(卷ID, -1);

    // 候选池 = 奖池的一次性副本，抽走一件就移除一件 ⇒ 同一批内不重复。
    // 必须用副本：直接删 奖池() 返回的平铺缓存会把持久数组抽空。
    var 候选 = 候选池(chr);
    var 记录 = [];     // [[道具ID, 件数], ...]（改成不重复后件数恒为 1，保留结构以便再调口径）
    var 定位 = {};
    var 落地 = 0;      // 背包放不下、改为掉在脚下的件数
    var 未发 = 0;      // 候选池抽干、实在发不出去的件数

    for (var i = 0; i < 次数; i++) {
        var id = 抽一件(候选);
        if (id === null) {
            未发++;
            continue;
        }
        var 落点 = 掉落_发一个(chr, id, true);   // true = 随机潜能，与 gainItem(id,1,true,true) 同口径
        if (落点 === '包') {
            计入(记录, 定位, id);
        } else if (落点 === '地') {
            计入(记录, 定位, id);
            落地++;
        } else {
            未发++;
        }
    }

    var 文本 = "#e#d【抽奖结果】#k#n  消耗 1 张 #i" + 卷ID + "# #t" + 卷ID + "#\r\n";
    文本 += "#d----------------------------------------#k\r\n";
    if (记录.length === 0) {
        文本 += "#r什么都没抽到。#k\r\n";
    } else {
        for (var n = 0; n < 记录.length; n++) {
            文本 += "#i" + 记录[n][0] + "# #b#t" + 记录[n][0] + "##k";
            文本 += 记录[n][1] > 1 ? (" #r×" + 记录[n][1] + "#k\r\n") : "\r\n";
        }
    }
    文本 += "#d----------------------------------------#k\r\n";
    文本 += "共获得 #r" + (次数 - 未发) + "#k 件装备";
    if (落地 > 0) {
        文本 += "，其中 #r" + 落地 + "#k 件背包放不下，#b已掉在你脚下#k，请#r自己拾取#k";
    }
    文本 += "。\r\n";
    if (未发 > 0) {
        文本 += "#d有 " + 未发 + " 件未能发放（候选池已空，奖池里没有可抽的装备了）。#k\r\n";
    }
    cm.sendOk(文本);
    cm.dispose();
}

function 计入(记录, 定位, 道具ID) {
    if (定位[道具ID] === undefined) {
        定位[道具ID] = 记录.length;
        记录.push([道具ID, 0]);
    }
    记录[定位[道具ID]][1]++;
}

// 建本批的候选池：奖池的一次性副本，建的时候一次把「已拥有的唯一件」剔掉。
// info/only == 1 的唯一件如果已经拥有，背包进不去、掉地上也捡不起来，留着只会白耗一次。
// 排除动作放在建池时、而不是抽取循环里重试，是有意的：
//   循环内重试会让「命中可用件」的概率随收集进度一路下滑（已收集 1000 件时只剩 13.3%，
//   重试 8 次仍全落空 = 31.9%，也就是卷照扣、什么都没给）。先筛后抽则没有这个问题，
//   本批最多 50 次、候选常年在 1100 件以上，抽不干。
function 候选池(chr) {
    var ii = 掉落_信息();
    var 源 = 奖池();
    var 出 = [];
    for (var i = 0; i < 源.length; i++) {
        var id = 源[i];
        if (ii.isPickupRestricted(id) && chr.haveItemWithId(id, true)) {
            continue;
        }
        出.push(id);
    }
    return 出;
}

// 从候选池等概率取一件，并把它移出候选池（同一批内不会再出现）。
// 移除用「尾元素补位 + pop」，O(1)；顺序被打乱不影响公平性 —— 每步都是按
// 当前下标等概率取，剩余集合上的分布依然是均匀的。
// 返回 null 只可能是候选池被抽干（单张卷最多 50 次，正常到不了这一步）。
function 抽一件(候选) {
    if (候选.length === 0) {
        return null;
    }
    var 位 = Math.floor(Math.random() * 候选.length);
    var id = 候选[位];
    候选[位] = 候选[候选.length - 1];
    候选.pop();
    return id;
}

// ============================================================
// 奖池：按分类平铺成一个大数组
// 这是**只读源**，抽取走的是 候选池() 建的副本 —— 千万别在这里原地删元素，
// 否则平铺缓存会被抽空，下一次开抽就没奖可抽了。
// ============================================================
var 平铺缓存 = null;

function 奖池() {
    if (平铺缓存 === null) {
        平铺缓存 = [];
        for (var 分类 in 起源奖池) {
            平铺缓存 = 平铺缓存.concat(起源奖池[分类]);
        }
    }
    return 平铺缓存;
}
